from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path

INSTALLER_VERSION="4.1.0-ALLIANCE-CRE-CHAMPIONSHIP-V4-INSTALLER"
MODULE_NAME="alliance_cre_championship_v410.py"
REGISTRAR="alliance_optional_property_modules.py"
MODULE_B64=""

def syntax_check(path):
    compile(path.read_text(encoding="utf-8"),str(path),"exec")

def main():
    root=Path.cwd()
    required=["alliance_cre_academy_v402.py","alliance_cre_academy_v401.py","alliance_cre_academy_v400.py",
              "alliance_failure_driven_mastery_v380.py","alliance_ownership_mastery_blind_v330.py","alliance_optional_property_modules.py"]
    missing=[x for x in required if not (root/x).exists()]
    if missing: raise SystemExit("Missing cumulative foundation files: "+", ".join(missing))

    registrar=root/REGISTRAR
    original=registrar.read_text(encoding="utf-8")
    stamp=datetime.now().strftime("%Y%m%d-%H%M%S")
    backup=root/f"{REGISTRAR}.before-v410-{stamp}.bak"
    shutil.copy2(registrar,backup)
    (root/MODULE_NAME).write_text(base64.b64decode(MODULE_B64).decode("utf-8"),encoding="utf-8")

    marker="# FOUNDATION 4.1 - Alliance CRE Championship Blind V4"
    if marker not in original:
        needle="    return result"; pos=original.rfind(needle)
        if pos<0: raise SystemExit("Final registrar return not found. Existing registrar was not modified.")
        block=r"""
    # FOUNDATION 4.1 - Alliance CRE Championship Blind V4
    # Certification only. No predictor tuning. Preserves 4.0.2 and all earlier foundations.
    try:
        if _route_exists(app, "/api/property-brain/championship-v410/status"):
            result["championship_v410"] = {"status":"ALREADY_REGISTERED","route":"/property-brain/championship-v410","error":None}
        else:
            import alliance_cre_championship_v410 as championship_v410
            result["championship_v410"] = {**championship_v410.register(core), "error": None}
    except Exception as exc:
        result["championship_v410"] = {"status":"ERROR","error":f"{type(exc).__name__}: {exc}","route":"/property-brain/championship-v410","fail_safe":True}

"""
        registrar.write_text(original[:pos]+block+original[pos:],encoding="utf-8")

    syntax_check(root/MODULE_NAME); syntax_check(registrar)
    reg=registrar.read_text(encoding="utf-8")
    checks={
      "v330":(root/"alliance_ownership_mastery_blind_v330.py").exists(),
      "v380":(root/"alliance_failure_driven_mastery_v380.py").exists() and "mastery_v380" in reg,
      "v400":(root/"alliance_cre_academy_v400.py").exists() and "academy_v400" in reg,
      "v401":(root/"alliance_cre_academy_v401.py").exists() and "academy_v401" in reg,
      "v402":(root/"alliance_cre_academy_v402.py").exists() and "academy_v402" in reg,
      "v410":"championship_v410" in reg
    }
    if not all(checks.values()): raise SystemExit("Cumulative verification failed: "+repr(checks))

    print("Alliance CRE Championship V4 installed successfully")
    print("Predictor: Foundation 4.0.2 frozen")
    print("Selection: fresh untouched 3.3 blind pool only; V1/V2/V3 excluded")
    print("Target: 20 independent cases")
    print("No tuning allowed until V4 score is frozen")
    print("Production/WhatsApp/Gold mutations: 0")
    print("Dashboard: /property-brain/championship-v410")
    print("Backup:",backup)

if __name__=="__main__":
    main()
